import { YEARS, SOURCES, ASSUMPTIONS, DATA_VERSION } from './data.js';
import { newGame, defaultDecision, advisorDecision, validateDecision, previewDecision, settleYear, summary, simulateStrategy, netWorth, liquidAssets, annualExpenses, currentAllocation, restoreGame, getChoices, balanceSheet, RULES, ASSET_KEYS, STOCK_KEYS, retailComparison } from './engine.js';
import { HISTORY_MEDIA } from './media.js';
import { buildDecisionContext, requestDecision, fallbackDecisionPack, requestPersona, fallbackPersona, validateApiConfig, getApiProviderHint } from './ai.js';
import { settleDuel, restoreDuel } from './session.js';
import { PROVIDERS } from './providers.js';

const $ = selector => document.querySelector(selector);
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const money = value => '$' + Math.round(value).toLocaleString('en-US');
const preciseMoney = value => '$' + value.toLocaleString('en-US', {minimumFractionDigits:2,maximumFractionDigits:2});
const signedMoney = value => (value >= 0 ? '+' : '−') + money(Math.abs(value));
const percent = value => (value >= 0 ? '+' : '−') + (Math.abs(value)*100).toFixed(1) + '%';
const colors = {cash:'#99b592',stock:'#376d58',tech:'#887eaf',consumer:'#d59874',health:'#7eafa8',bond:'#8eabc1',gold:'#d7b66c'};
const names = {cash:'现金',stock:'宽基股票',tech:'科技',consumer:'消费',health:'医疗',bond:'国债',gold:'黄金',home:'自住房',car:'家庭汽车',mortgage:'住房按揭',shortfallDebt:'缺口借款'};
const GROUPS = ['cash','equity','bond','gold'];
const groupNames = {cash:'现金牌',equity:'股票牌',bond:'国债牌',gold:'黄金牌'};
const sectorDescriptions = {stock:'覆盖大型美股，多行业组合',tech:'计算机、软件与通信等行业',consumer:'消费品、零售与服务等行业',health:'医疗、药品与相关服务'};
const sectorIcons = {stock:'◈',tech:'⌘',consumer:'◇',health:'✚'};
const PRESETS = {steady:{cash:35,equity:20,bond:35,gold:10},balanced:{cash:20,equity:40,bond:30,gold:10},growth:{cash:10,equity:70,bond:10,gold:10}};
const SAVE_KEY='life-cfo-save-v3';
const LEGACY_KEY='life-cfo-save-v2';
const VISITED_KEY='life-cfo-played-v3';
let state=newGame(), decision, page='game', chosen=false, replay=false, pendingReview=false, saving=true;
let rivalState=newGame('rival'), agentRounds=[], agentPack=null, persona=null;
let agentStatus='idle', agentError='', personaStatus='idle', personaError='', agentEnabled=false;
let apiConfig={endpoint:'https://aigc.efunds.com.cn/v1/chat/completions',model:'gpt-4o',apiKey:''};
let requestEpoch=0, agentController=null, personaController=null, legacyVersion='v0.2';
let parentDialog=null, modalReturnFocus=null, initialMessage='', legacyRaw=null, selectedSector='stock', newsTab=0, ledgerYear=null;
try {
  legacyRaw=localStorage.getItem(LEGACY_KEY);
  if(!legacyRaw){legacyRaw=localStorage.getItem('life-cfo-save-v1');legacyVersion='v0.1';}
  replay=localStorage.getItem(VISITED_KEY)==='true';
  const raw=localStorage.getItem(SAVE_KEY);
  if(raw){
    const save=JSON.parse(raw);
    if(save.dataVersion!==DATA_VERSION || !['player','assisted','auto'].includes(save.state?.mode)) throw new Error('存档版本不匹配');
    const restored=restoreDuel(save);state=restored.player;rivalState=restored.rival;agentRounds=restored.rounds;agentPack=restored.pack;persona=restored.persona;
    agentEnabled=save.agentEnabled===true;
    if(save.apiPreference?.endpoint&&save.apiPreference?.model){try{const preference=validateApiConfig({...save.apiPreference,apiKey:'restore-placeholder'});apiConfig={...preference,apiKey:''};}catch{}}
    agentStatus=agentPack?'ready':'idle';
    if(save.draft && validateDecision(state,save.draft).valid){decision=save.draft;chosen=Boolean(save.chosen);}
    replay=Boolean(save.replay);
    pendingReview=Boolean(save.pendingReview)&&state.round>0;
    initialMessage=state.round?'存档已载入，继续你的旅程。':'';
  } else if(legacyRaw) initialMessage=legacyVersion+' 旅程已封存保留；双人新规则将开启独立存档。';
} catch { state=newGame();rivalState=newGame('rival');agentRounds=[];agentPack=null;persona=null;decision=null;chosen=false;pendingReview=false;initialMessage='当前存档无法核验，已安全开启新旅程。'; }
if(!decision)decision=state.mode==='auto'?advisorDecision(state):defaultDecision(state);
function syncSector(){selectedSector=STOCK_KEYS.reduce((best,key)=>decision.allocation[key]>decision.allocation[best]?key:best,'stock');}
function scenarioBanner(){const y=YEARS[state.round];return y?.dataKind==='scenario'?'<div class="scenario-banner"><b>2026 · 模拟终章</b><span>这一年的完整历史尚未发生。以下是架空情景，结算为模拟结果，不是预测。</span></div>':'';}

function agentName(pack=agentPack){return pack?.source==='model'?'AI 同桌':'规则陪练';}
function planText(d){return ASSET_KEYS.filter(k=>d.allocation[k]>0).map(k=>`${names[k]} ${d.allocation[k]}%`).join(' · ');}
function agentCard(){
  const ready=!!agentPack&&agentStatus==='ready';
  const label=agentStatus==='running'?'正在研读本轮情报':agentStatus==='error'?'连接未完成':agentStatus==='needs-key'?'等待重新连接':ready?`${agentName()} · 本年已备牌`:'等待入座';
  return `<section class="agent-card card" aria-live="polite"><div class="agent-card-heading"><span class="agent-avatar ${agentStatus==='running'?'thinking':''}">✦</span><div><small>YOUR COMPANION / 同桌挑战者</small><h2>${label}</h2></div><span class="online-dot ${ready?'ready':''}"></span></div><div class="duel-score"><div><small>你的净资产</small><b>${money(netWorth(state))}</b></div><span>VS</span><div><small>同桌净资产</small><b>${money(netWorth(rivalState))}</b></div></div><p>${agentStatus==='running'?'同一年的背景，各自下判断。正在生成分析与双方独立计划…':agentStatus==='error'?esc(agentError):agentStatus==='needs-key'?'密钥不随存档保存。重新填写密钥，或明确选择本年规则替补。':ready?esc(agentPack.summary):'配置自己的模型，让一位 AI 与你一起走过二十年。'}</p><div class="agent-card-actions">${ready?'<button class="secondary" data-action="advisor">翻开分析卡 ↗</button>':agentStatus==='error'?'<button class="secondary" data-action="ai-retry">重试连接</button>':''}<button class="text-btn" data-action="ai-settings">${agentEnabled?'连接设置':'接入我的 AI'}</button>${['error','needs-key','running'].includes(agentStatus)?'<button class="text-btn" data-action="ai-fallback">本年用规则陪练</button>':''}</div><small class="agent-footnote">${agentPack?.source==='model'?`${esc(agentPack.model)} · 决定已封存，结算前不可重抽`:agentEnabled?'仅发送当前情报和虚拟账本':'未接入大模型 · 规则陪练也拥有独立账本'}</small></section>`;
}

function cancelAgentRequests(){requestEpoch++;agentController?.abort();personaController?.abort();agentController=null;personaController=null;if(agentStatus==='running')agentStatus='idle';if(personaStatus==='running')personaStatus='idle';}
function prepareRound(){
  if(state.round>=YEARS.length||pendingReview)return;
  if(agentPack){agentStatus='ready';if(state.mode==='auto'){decision=structuredClone(agentPack.playerDecision);chosen=true;syncSector();}return;}
  if(!agentEnabled){agentPack=fallbackDecisionPack(state,rivalState);agentStatus='ready';if(state.mode==='auto'){decision=structuredClone(agentPack.playerDecision);chosen=true;syncSector();}return;}
  if(!apiConfig.apiKey){agentStatus='needs-key';return;}
  if(agentStatus!=='running'&&agentStatus!=='error')void askAgent();
}
async function askAgent(){
  if(state.round>=YEARS.length||pendingReview||agentStatus==='running'||agentPack?.source==='model')return;
  if(!apiConfig.apiKey){agentStatus='needs-key';render();return;}
  const epoch=++requestEpoch, round=state.round;
  agentController?.abort();agentController=new AbortController();
  agentPack=null;agentStatus='running';agentError='';render();
  try{
    const pack=await requestDecision(apiConfig,buildDecisionContext(state,rivalState),{signal:agentController.signal});
    if(epoch!==requestEpoch||state.round!==round)return;
    agentPack=pack;agentStatus='ready';
    if(state.mode==='auto'){decision=structuredClone(pack.playerDecision);chosen=true;syncSector();}
    render();toast('同桌已封存本年决定，分析卡可以翻开了。');
  }catch(error){
    if(epoch!==requestEpoch||state.round!==round)return;
    agentStatus='error';agentError=error.message||'连接失败，请重试或选用规则陪练。';render();
  }
}
function useRuleFallback(){
  if(agentPack?.source==='model'){toast('本年的 AI 决定已封存，下一年才可更换。');return;}
  cancelAgentRequests();agentPack=fallbackDecisionPack(state,rivalState);agentStatus='ready';agentError='';
  if(state.mode==='auto'){decision=structuredClone(agentPack.playerDecision);chosen=true;syncSector();}
  closeModal();render();toast('本年明确使用规则陪练，来源会记入账本。');
}
function aiSettings(){
  showModal('给你的 AI 搭档一个座位。',`<div class="api-intro"><span class="agent-avatar">✦</span><p>连接支持 Chat Completions 的兼容接口。每轮一次请求同时生成分析和双方计划；通关后再生成一次个性化画像。用量和输出额度采用服务商设置，调用费用由服务商计算。</p></div><form id="ai-settings-form"><label class="api-field">快速选择服务<select id="api-provider"><option value="">选择服务，或在下方填写自定义地址</option>${PROVIDERS.filter(p=>p.id!=='deepseek-v1').map(p=>`<option value="${esc(p.endpoint)}">${esc(p.name)}</option>`).join('')}</select></label><label class="api-field">服务地址（base_url 或完整接口）<input id="api-endpoint" type="url" autocomplete="off" spellcheck="false" value="${esc(apiConfig.endpoint)}" placeholder="https://你的服务商/v1/chat/completions"></label><label class="api-field">模型名称<input id="api-model" autocomplete="off" spellcheck="false" value="${esc(apiConfig.model)}" placeholder="填写服务商提供的模型 ID"></label><label class="api-field">API 密钥<input id="api-key" type="password" autocomplete="off" spellcheck="false" placeholder="${apiConfig.apiKey?'同一服务地址可留空保留；更换地址请重新填写':'粘贴真实密钥，不是环境变量名'}"></label><p class="table-note">易方达、OpenAI、DeepSeek、通义千问、智谱与 Moonshot 官方地址经游戏转发服务请求；该服务只为本次调用使用你的密钥，不保存。其他兼容地址由浏览器直连，需要服务商允许跨域（CORS）。只发送本轮情报与虚拟家庭账本；密钥不写存档、不导出，刷新后需重新填写。支持 HTTPS 或本机 HTTP。</p><div class="api-boundary"><b>同年背景，匿名分析</b><p>模型读取玩家也能查看的三条匿名摘要与双方账本；摘要去掉了日期、实体名称和精确历史数值。请求不含未来行情或未发生事件。预训练记忆仍无法彻底消除，因此这不是严格等信息的模型能力测评。</p></div>${agentPack?.source==='model'?'<p class="subtle-warning">本年决定已封存，修改连接只影响下一回合。</p>':''}<div id="api-settings-error" role="alert"></div><div class="modal-actions"><button class="primary" type="button" data-action="ai-connect">连接并启用 AI</button><button class="secondary" type="button" data-action="ai-disconnect">使用本地规则陪练</button></div></form>`,{wide:true,kicker:'CONNECT YOUR MODEL · 玩家自行配置'});
}
document.addEventListener('change',event=>{
  if(event.target?.id!=='api-provider'||!event.target.value)return;
  $('#api-endpoint').value=event.target.value;
  $('#api-model').value=getApiProviderHint(event.target.value).defaultModel;
  $('#api-key').value='';
  $('#api-endpoint').dispatchEvent(new Event('input',{bubbles:true}));
});
document.addEventListener('input',event=>{
  if(event.target?.id!=='api-endpoint')return;
  const field=$('#api-key');if(!field)return;
  try{const candidate=validateApiConfig({endpoint:event.target.value,model:$('#api-model').value,apiKey:'validate-endpoint-only'});field.placeholder=apiConfig.apiKey&&candidate.endpoint===apiConfig.endpoint?'同一服务地址可留空保留当前密钥':'地址已更换，请填写该服务的密钥';}catch{field.placeholder='请填写该服务的密钥';}
});
function connectAgent(){
  try{
    const endpoint=$('#api-endpoint').value.trim(), model=$('#api-model').value.trim();
    const normalized=validateApiConfig({endpoint,model,apiKey:'validate-endpoint-only'});
    const enteredKey=$('#api-key').value.trim();
    if(!enteredKey&&normalized.endpoint!==apiConfig.endpoint)throw new Error('服务地址已更换，请重新填写该服务的 API 密钥。');
    const config=validateApiConfig({endpoint,model,apiKey:enteredKey||apiConfig.apiKey});
    cancelAgentRequests();apiConfig=config;agentEnabled=true;$('#api-key').value='';closeModal();
    if(state.round===YEARS.length){render();void ensurePersona(true);}else if(agentPack?.source==='model'){render();toast('本年决定保持封存，新配置从下一年开始。');}else{agentPack=null;agentStatus='idle';void askAgent();}
  }catch(error){$('#api-settings-error').innerHTML=`<p class="error">${esc(error.message)}</p>`;}
}
function disconnectAgent(){cancelAgentRequests();apiConfig.apiKey='';agentEnabled=false;closeModal();if(state.round<YEARS.length){if(agentPack?.source!=='model')agentPack=fallbackDecisionPack(state,rivalState);agentStatus='ready';if(state.mode==='auto'){decision=structuredClone(agentPack.playerDecision);chosen=true;syncSector();}}else if(!persona)persona=fallbackPersona(state,rivalState);render();toast(agentPack?.source==='model'?'密钥已清除；本年 AI 决定保留，下年改用规则陪练。':'密钥已清除，后续使用本地规则陪练。');}
function advisor(){
  if(!agentPack){showModal('同桌还在准备这一年的牌。',`<p>${esc(agentStatus==='error'?agentError:agentStatus==='needs-key'?'请重新填写 API 密钥，或为本年选择规则陪练。':'请等待分析完成。')}</p><div class="modal-actions"><button class="primary" data-action="ai-settings">连接设置</button><button class="secondary" data-action="ai-fallback">本年用规则陪练</button></div>`);return;}
  const pack=agentPack,context=buildDecisionContext(state,rivalState);
  const plan=(d,account)=>`<div class="advice-plan"><small>${account}</small><p>${esc(planText(d))}</p><b>${esc(getChoices(account==='给你的建议'?state:rivalState).find(c=>c.id===d.choiceId)?.label)}</b><span>${d.insurance?'医疗保障开启':'不投保'} · ${d.rebalance==='hold'?'维持持仓':'年度调仓'}${d.buyHome?' · 购房':''}${d.buyCar?' · 购车':''}</span></div>`;
  showModal(`${agentName()}的分析，摊开看。`,`<div class="analysis-intro"><span class="pill">${pack.source==='model'?esc(pack.model):'本地规则 · 不调用大模型'}</span><p>${esc(pack.summary)}</p></div><div class="analysis-grid">${pack.analysis.map((a,i)=>{const signal=context.signals.find(s=>s.id===a.signalId);return `<article class="analysis-note"><small>情报 ${i+1} · ${esc(a.signalId)}</small><blockquote>${esc(a.observation)}</blockquote><p><b>如何理解</b>${esc(a.reasoning)}</p><p class="analysis-risk"><b>仍需警惕</b>${esc(a.risk)}</p><details><summary>核对所引用的原始情报</summary><p>${esc(signal?.text)}</p></details></article>`;}).join('')}</div><div class="dual-plans">${plan(pack.playerDecision,'给你的建议')}${plan(pack.rivalDecision,'同桌自己的决定')}</div><p class="table-note">同桌决定已在揭晓前封存。你可以采纳后修改；托管执行的是针对你账户的建议。双方收入和生活选择独立演化，净资产差距不等于纯投资能力。</p><button class="primary wide" data-action="${state.mode==='auto'?'close-modal':'apply-advisor'}">${state.mode==='auto'?'了解，等待年度揭晓':'采纳建议，再由我决定是否出发'}</button>`,{wide:true,kicker:'THINK BEFORE YOU ACT · 当前情报限定'});
}

function duelResult(index,{full=false}={}){
  const p=state.history[index],r=rivalState.history[index],pack=agentRounds[index];if(!p||!r||!pack)return '';
  const result=(label,h)=>`<div><small>${label}</small><strong class="${h.portfolioReturn>=0?'up':'down'}">${percent(h.portfolioReturn)}</strong><span>金融组合年收益 · 税费前</span><b>${money(h.endNetWorth)}</b><span>年末净资产</span></div>`;
  return `<section class="duel-result"><div class="section-heading"><h3>这一回合，你与${agentName(pack)}</h3><span class="mini-label">${pack.source==='model'?esc(pack.model):'规则替补 / 未调用 AI'}</span></div><div class="duel-result-numbers">${result('你',p)}<em>VS</em>${result('同桌',r)}</div><p><b>同桌出牌：</b>${esc(planText(pack.rivalDecision))}${pack.rivalDecision.rebalance==='hold'?'（维持持仓，目标比例未执行）':''}</p><p><b>家庭选择：</b>${esc(r.choiceLabel)} · 生活值 ${r.lifeScore} · 本年净投入 ${signedMoney(r.netContribution)}</p><details ${full?'open':''}><summary>展开同桌的资产负债表与封存分析</summary>${sheetTable(r.startBalanceSheet,r.endBalanceSheet)}<p>${esc(pack.summary)}</p>${pack.analysis.map(a=>`<p class="rival-analysis"><q>${esc(a.observation)}</q><br>${esc(a.reasoning)}<br><small>风险：${esc(a.risk)}</small></p>`).join('')}</details><p class="table-note">同起点、同市场、同外生事件；投资回报独立于工资入金。家庭选择不同，净资产不可当作单一配置的胜负。</p></section>`;
}
function annualRanking(h,y){const rank=retailComparison(h);if(!rank.available)return `<section class="annual-ranking"><span>本年未参与模拟分位</span><div>年初没有可投资本金</div><p>年度工资不倒算为年初投入，不以零收益参与排名。</p><blockquote>“${esc(y.roast||y.reveal.lesson)}”</blockquote></section>`;return `<section class="annual-ranking"><span>中国散户风格模拟参照池</span><div>收益率超过 <strong>${Number(rank.strictBeatPct).toFixed(1)}%</strong> 的模拟散户</div><p>你的金融组合 ${percent(h.portfolioReturn)} · ${rank.sampleSize} 个虚构策略 · 同收益口径</p><details><summary>这是游戏分位，不是真实中国散户统计</summary><p>${esc(rank.method)}。全体使用游戏中的美元资产篮子，无法推断真实 A 股投资者排名；同收益不计为被超过；展开方法中的中位分位是另一统计口径。</p></details><blockquote>“${esc(y.roast||y.reveal.lesson)}”</blockquote>${y.dataKind==='scenario'?'<small>本年回报与锐评来自架空情景。</small>':''}</section>`;}

function personaView(){const p=persona;return `<section class="persona-card card"><div class="section-heading"><div><div class="eyebrow">YOUR INVESTOR PERSONA</div><h2>二十年的选择，拼成一个你。</h2></div><span class="persona-seal">✧</span></div>${p?`<span class="pill">${p.source==='model'?'AI 个性化画像 · '+esc(p.model):'规则行为画像 · 尚未使用大模型'}</span><h3>${esc(p.title)}</h3><p class="persona-description">${esc(p.description)}</p><div class="persona-risk"><small>本局风险偏好</small><b>${esc(p.riskPreference?.label||'见行为分析')}</b><p>${esc(p.riskPreference?.description||'结合真实配置与家庭取舍观察，不作心理诊断。')}</p></div><div class="persona-traits">${(p.traits||[]).map(t=>`<div><b>${esc(t.label)}</b><p>${esc(t.description)}</p></div>`).join('')}</div><h4>把几个具体的选择，拿出来聊聊</h4><div class="persona-evidence">${p.evidence.map(e=>`<article><span>${e.year}${YEARS.find(y=>y.year===e.year)?.dataKind==='scenario'?' · 模拟':''}</span><blockquote>${esc(e.quote)}</blockquote><p>${esc(e.interpretation)}</p></article>`).join('')}</div><p class="table-note">${esc(p.caveat)} · 这是本局行为复盘，不是专业人格或心理诊断。</p>`:`<p>${personaStatus==='running'?'正在把二十年的决策整理成你的画像…':personaStatus==='error'?esc(personaError):'接入模型，让 AI 从真实决策中分析你的取舍、风险偏好与成长。'}</p>`}<div class="modal-actions">${p?.source==='model'?'':personaStatus==='running'?'<span class="thinking-label">✦ 正在回看你的旅程</span>':`<button class="primary" data-action="persona-generate">${apiConfig.apiKey?'生成 AI 个性化画像':'连接 AI，生成我的画像'}</button>`}${!p&&personaStatus!=='running'?'<button class="secondary" data-action="persona-fallback">先看规则复盘</button>':''}</div></section>`;}
async function ensurePersona(force=false){
  if(state.round!==YEARS.length||persona?.source==='model'||personaStatus==='running')return;
  if(!force&&persona)return;
  if(!agentEnabled&&!force){persona=fallbackPersona(state,rivalState);render();return;}
  if(!apiConfig.apiKey){personaStatus='needs-key';render();return;}
  const epoch=++requestEpoch;personaController=new AbortController();personaStatus='running';personaError='';render();
  try{const result=await requestPersona(apiConfig,state,rivalState,{signal:personaController.signal});if(epoch!==requestEpoch||state.round!==YEARS.length)return;persona=result;personaStatus='ready';render();toast('你的二十年人格画像已生成。');}
  catch(error){if(epoch!==requestEpoch)return;personaStatus='error';personaError=error.message||'画像生成失败，可重试。';render();}
}
syncSector();
const icon = (name,cls='') => {
 const paths={chart:'<path d="M4 19h16M7 15V10m5 5V5m5 10V8"/>',book:'<path d="M12 6c-3-2-7-2-9-1v14c2-1 6-1 9 1 3-2 7-2 9-1V5c-2-1-6-1-9 1v14"/>',life:'<path d="M12 20s-8-5-8-11a4 4 0 0 1 8-1 4 4 0 0 1 8 1c0 6-8 11-8 11Z"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 5 2c-1 1-2 1-2 3m0 3h.01"/>',arrow:'<path d="M4 12h15m-5-5 5 5-5 5"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',spark:'<path d="m12 3 2.3 6.7L21 12l-6.7 2.3L12 21l-2.3-6.7L3 12l6.7-2.3L12 3Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',check:'<path d="m5 12 4 4L19 6"/>',reset:'<path d="M4 10a8 8 0 1 1 1 7M4 4v6h6"/>',home:'<path d="m3 11 9-8 9 8M5 10v11h14V10m-10 11v-8h6v8"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>'};
 return `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.spark}</svg>`;
};
function persist(){
  try {localStorage.setItem(SAVE_KEY,JSON.stringify({dataVersion:DATA_VERSION,state,rivalState,agentRounds,agentPack,persona,agentEnabled,apiPreference:{endpoint:apiConfig.endpoint,model:apiConfig.model},draft:decision,chosen,replay,pendingReview}));saving=true;}
  catch {saving=false;}
}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function header(){return `<header class="site-header"><a class="brand" href="#" data-action="nav" data-page="game" aria-label="人生 CFO 首页"><span class="brand-mark">${icon('chart')}</span><div><b>人生 CFO</b><small>一场关于选择的冒险</small></div></a><nav aria-label="主导航">${[['game','旅程','globe'],['ledger','账本','book'],['profile','相册','life']].map(([key,title,i])=>`<button data-action="nav" data-page="${key}" class="nav-btn ${page===key?'active':''}" ${page===key?'aria-current="page"':''}>${icon(i)}${title}</button>`).join('')}</nav><div class="header-actions"><button class="agent-config-button" data-action="ai-settings">✦ AI 搭档</button><span class="version">v0.9 · 预发行</span><button class="icon-btn" data-action="help" aria-label="游戏指南">${icon('help')}</button></div></header>`;}
function footer(){return `<footer><span>历史市场 × 模拟人生 · 美元计价</span><div><span class="save-status">● ${saving?'进度已保存':'存档不可用'}</span><button data-action="sources" class="text-btn">资料室</button>${legacyRaw?'<button data-action="export-legacy" class="text-btn">旧版封存</button>':''}<button data-action="restart" class="text-btn">新的人生</button></div></footer>`;}
function modePicker(){return `<div class="mode-picker" role="group" aria-label="决策模式">${[['player','自己玩'],['assisted','搭档建议'],['auto','搭档托管']].map(([mode,title])=>`<button data-action="mode" data-mode="${mode}" class="${state.mode===mode?'active':''}" aria-pressed="${state.mode===mode}">${title}</button>`).join('')}</div>`;}
function gameHud(){const s=summary(state),y=YEARS[state.round];return `<div class="game-hud"><div class="chapter-heading"><div class="eyebrow">${esc(y.chapter)} · 第 ${state.round+1} / ${YEARS.length} 回合</div><h1><span class="year-number">${y.year}</span><span>${esc(y.title)}</span></h1><p>林舟与阿宁 · ${state.age} 岁${replay?' · 已知剧情重玩':''}</p></div><div class="resource-bar"><button data-action="nav" data-page="ledger" class="resource"><span class="resource-symbol coin">＄</span><span><small>家庭净资产</small><strong>${money(s.netWorth)}</strong></span></button><div class="resource"><span class="resource-symbol heart">♡</span><span><small>生活值</small><strong>${state.lifeScore}<em>/100</em></strong></span></div><button data-action="goals" class="resource goals-resource"><span class="resource-symbol star">✧</span><span><small>人生约定</small><strong>${s.goals.filter(g=>g.achieved).length}<em>/3</em></strong></span></button></div></div>`;}
function timeline(){return `<div class="journey-track" aria-label="二十年旅程">${YEARS.map((y,i)=>`<button class="journey-node ${i<state.round?'done':i===state.round?'current':'locked'}" ${i<state.round?`data-action="review" data-index="${i}"`:'disabled'} title="${y.year}${i<state.round?' · 查看已完成回合':i===state.round?' · 当前回合':' · 未解锁'}"><span>${i<state.round?'✓':String(i+1).padStart(2,'0')}</span><small>${y.year}</small></button>`).join('')}<div class="journey-finish">${icon('home')}<small>50岁</small></div></div>`;}
function photoCard(year,{compact=false,interactive=true}={}){const m=HISTORY_MEDIA[year];if(!m)return '';return `<figure class="history-photo ${compact?'compact':''}"><img src="${esc(m.path)}" alt="${esc(m.alt||m.title)}" ${compact?'loading="lazy"':''}><div class="photo-grain"></div><span class="photo-date">${year} · ${m.kind==='scenario'?'架空情景':'时代切片'}</span>${interactive?`<button class="photo-credit" data-action="photo" data-year="${year}" aria-label="查看${year}年影像出处">ⓘ ${m.kind==='scenario'?'模拟插画':m.kind==='illustration'?'历史主题图解':'历史照片'}</button>`:''}<figcaption><span class="photo-kicker">${compact?'这一年的记忆':'你来之前，世界刚刚发生'}</span><h2>${esc(m.title)}</h2><p>${esc(m.caption)}</p></figcaption></figure>`;}
function briefing(){const y=YEARS[state.round],items=y.briefing,active=items[Math.min(newsTab,items.length-1)];return `<section class="briefing card"><div class="section-heading"><h2><span class="section-number">情报</span> 站在这一年的起点</h2><span class="mini-label">${y.year} 年初可见</span></div><div class="news-tabs" role="tablist" aria-label="年度情报">${items.map((n,i)=>`<button role="tab" aria-selected="${newsTab===i}" class="${newsTab===i?'active':''}" data-action="news" data-index="${i}">${esc(n.tag)}</button>`).join('')}</div><article class="news-story" role="tabpanel"><h3>${esc(active.title)}</h3><p>${esc(active.text)}</p></article><div class="market-signals">${(y.marketSignals||[]).map(s=>`<div title="${esc(s.context)}"><small>${esc(s.label)}</small><strong>${esc(s.value)}</strong><span>${esc(s.asOf||'已公布资料')}</span></div>`).join('')}</div><button class="text-btn signal-more" data-action="intel">${icon('book')} 阅读完整情报与来源</button></section>`;}
function family(){const y=YEARS[state.round],auto=state.mode==='auto';return `<section class="family-card card"><div class="section-heading"><h2><span class="section-number">01</span> 生活给你出了一道题</h2><span class="mini-label">${auto||chosen?'已选定 ✓':'二选一'}</span></div><div class="dialogue"><span class="character-avatar">${state.round<3?'☕':state.round<7?'⌂':'✿'}</span><div><small>${esc(y.family.speaker)}</small><p>“${esc(y.family.quote)}”</p></div></div><div class="choices" role="group" aria-label="本年家庭选择">${getChoices(state).map((c,i)=>`<button class="choice ${(chosen||auto)&&decision.choiceId===c.id?'selected':''}" data-action="choice" data-choice="${esc(c.id)}" aria-pressed="${(chosen||auto)&&decision.choiceId===c.id}" ${auto?'disabled':''}><span class="choice-letter">${String.fromCharCode(65+i)}</span><span class="choice-copy"><b>${esc(c.label)}</b><small>${esc(c.description)}</small></span><span class="choice-check">${(chosen||auto)&&decision.choiceId===c.id?'✓':'↗'}</span></button>`).join('')}</div></section>`;}
function grouped(allocation=decision.allocation){return {cash:allocation.cash,equity:STOCK_KEYS.reduce((sum,key)=>sum+allocation[key],0),bond:allocation.bond,gold:allocation.gold};}
function distributeGroup(weights){const previousEquity=STOCK_KEYS.reduce((sum,key)=>sum+decision.allocation[key],0);let used=0;STOCK_KEYS.forEach((key,i)=>{const n=i===STOCK_KEYS.length-1?weights.equity-used:Math.floor(weights.equity*(previousEquity?decision.allocation[key]/previousEquity:key===selectedSector?1:0));decision.allocation[key]=n;used+=n;});if(!previousEquity){STOCK_KEYS.forEach(k=>decision.allocation[k]=k===selectedSector?weights.equity:0);}for(const key of ['cash','bond','gold'])decision.allocation[key]=weights[key];}
function allocationBar(){const groups=grouped(),groupColors={cash:colors.cash,equity:colors.stock,bond:colors.bond,gold:colors.gold};return `<div class="allocation-bar" aria-label="目标配置">${GROUPS.map(k=>`<span style="width:${groups[k]}%;background:${groupColors[k]}" title="${groupNames[k]} ${groups[k]}%"></span>`).join('')}</div>`;}
function portfolio(){const a=grouped(),auto=state.mode==='auto',hold=decision.rebalance==='hold',p=previewDecision(state,decision);return `<section class="portfolio-card card"><div class="section-heading"><h2><span class="section-number">02</span> 组好你的投资牌</h2><button class="text-btn" data-action="allocation-help">怎么玩 ${icon('help')}</button></div><div class="preset-row">${[['steady','稳扎稳打'],['balanced','攻守兼备'],['growth','大胆出发']].map(([id,t])=>`<button data-action="preset" data-preset="${id}" class="${GROUPS.every(k=>a[k]===PRESETS[id][k])?'active':''}" ${auto||hold?'disabled':''}>${t}</button>`).join('')}</div><div class="asset-hand">${GROUPS.map((k,i)=>`<div class="asset-card asset-${k}"><div class="asset-card-top"><span class="asset-emblem">${['◉','↗','▥','◆'][i]}</span><label for="allocation-${k}">${groupNames[k]}</label><strong data-allocation-value="${k}">${a[k]}<small>%</small></strong></div><input id="allocation-${k}" type="range" min="0" max="100" step="1" value="${a[k]}" data-asset="${k}" aria-label="${groupNames[k]}比例" ${auto||hold?'disabled':''}></div>`).join('')}</div><div id="allocation-bar">${allocationBar()}</div><div class="sector-heading"><span>股票牌里装什么？</span><span id="sector-current">${STOCK_KEYS.filter(k=>decision.allocation[k]>0).length>1?'混合板块':names[selectedSector]}</span></div><div class="sector-picker" role="group" aria-label="股票板块">${STOCK_KEYS.map(k=>`<button class="sector-card ${decision.allocation[k]===a.equity&&a.equity>0?'active':''}" data-action="sector" data-sector="${k}" aria-pressed="${decision.allocation[k]===a.equity&&a.equity>0}" title="${sectorDescriptions[k]}" ${auto||hold?'disabled':''}><span>${sectorIcons[k]}</span>${k==='stock'?'宽基':names[k]}</button>`).join('')}</div><p class="proxy-note">${esc(YEARS[state.round]?.sectorProxy||'板块采用 French 行业研究组合，非可直接交易产品')}</p><div id="budget-preview">${budgetPreview(p)}</div><button class="life-plan-button" data-action="life-plan">${icon('home')} 生活计划 <span>${decision.insurance?'医疗保障 ✓':'未选保障'}${decision.buyHome?' · 买房':''}${decision.buyCar?' · 买车':''}</span><b>＋</b></button><div id="decision-errors">${p.errors.length?`<div class="error">${p.errors.map(esc).join('<br>')}</div>`:''}</div><button class="primary settle-button" id="settle-button" data-action="settle" ${(!auto&&!chosen)||!p.valid||!agentPack||agentStatus==='running'?'disabled':''}><span>${agentStatus==='running'?'搭档正在思考…':auto?'让搭档出牌':!chosen?'先选一张生活事件卡':'就这样，出发！'}</span><span>${yLabel()} ${icon('arrow')}</span></button><p class="turn-hint">${agentPack?.source==='model'?'本年 AI 决定已封存 · 双方同时结算':agentPack?'本年由规则陪练出牌 · 双方同时结算':'等待搭档封存决定，再一起出发'}</p></section>`;}
function yLabel(){return `${YEARS[state.round]?.year??2026} →`;}
function budgetPreview(p){return `<div class="budget-line"><span>${chosen||state.mode==='auto'?'年初计划支出':'首项方案预览'} <b>${money(p.upfrontCost)}</b></span><span>预计交易费 <b>${money(p.fees)}</b></span></div>${decision.rebalance==='hold'?'<p class="subtle-warning">持仓模式：本年维持资产，不执行目标比例。</p>':''}`;}
function gamePage(){if(state.round>=YEARS.length)return endingPage();return `${gameHud()}${timeline()}${scenarioBanner()}${agentCard()}<div class="game-layout"><div class="world-column">${photoCard(YEARS[state.round].year-1)}${briefing()}<div class="narrator-note"><span>✦</span><p>${esc(HISTORY_MEDIA[YEARS[state.round].year-1]?.meme||'世界有它的节奏，生活有你的选择。')}</p><small>旁白小声说</small></div></div><div class="decision-column">${family()}${portfolio()}</div></div><div class="play-controls">${modePicker()}<div><button data-action="advisor" class="advisor-call">✧ 查看搭档分析</button><button class="text-btn" data-action="goals">${icon('life')} 查看本局约定</button></div></div>`;}
function goals(){const s=summary(state);return `<div class="goal-list">${s.goals.map((g,i)=>`<div class="goal"><span class="goal-icon">${['⚑','◈','♡'][i]}</span><div><h3>${esc(g.label)}</h3><div class="progress-track"><div style="width:${g.progress*100}%"></div></div><p>${g.achieved?'已达成 ✓':i===0?`${g.value} / ${YEARS.length} 年`:i===1?`${money(g.value)} / ${money(g.target)}`:`${g.value} / ${g.target}`}</p></div></div>`).join('')}</div>`;}
function badges(){return [
 {id:'first',name:'故事开场',symbol:'✦',unlocked:state.round>=1,detail:'完成第一个年度'},
 {id:'care',name:'有人撑伞',symbol:'☂',unlocked:state.history.some(h=>h.insurancePayout>0),detail:'医疗保障产生实际赔付'},
 {id:'home',name:'一盏自己的灯',symbol:'⌂',unlocked:state.homeValue>0,detail:'购入一套自住房'},
 {id:'life',name:'日子有滋有味',symbol:'♡',unlocked:state.history.some(h=>h.lifeScore>=75),detail:'生活满意度曾达到75'},
 {id:'diverse',name:'不只一张牌',symbol:'◈',unlocked:state.history.some(h=>STOCK_KEYS.filter(k=>h.allocation[k]>0.01).length>=3),detail:'一次实际持仓包含三个股票方向'},
 {id:'finish',name:'岁月收藏家',symbol:'⚑',unlocked:state.round===YEARS.length,detail:'走完二十年旅程'}
];}
function sheetTable(start,end){const assetRows=[...ASSET_KEYS,'home','car'];const row=(name,a,b,cls='')=>`<tr class="${cls}"><th scope="row">${name}</th><td>${preciseMoney(a)}</td><td>${preciseMoney(b)}</td><td class="${b-a>=0?'up':'down'}">${b-a>=0?'+':'−'}${preciseMoney(Math.abs(b-a))}</td></tr>`;return `<div class="sheet-equation"><span>总资产<b>${money(end.totalAssets)}</b></span><i>−</i><span>总负债<b>${money(end.totalLiabilities)}</b></span><i>=</i><span class="net"><em>净资产</em><b>${money(end.netWorth)}</b></span></div><p class="mobile-table-hint">← 左右滑动，查看年初、年末与变化 →</p><div class="table-wrap"><table class="balance-sheet"><thead><tr><th>项目 · 美元</th><th>年初</th><th>年末</th><th>变化</th></tr></thead><tbody><tr class="table-section"><th colspan="4">资产 · 你拥有的</th></tr>${assetRows.map(k=>row(names[k],start.assets[k],end.assets[k])).join('')}${row('资产合计',start.totalAssets,end.totalAssets,'subtotal')}<tr class="table-section"><th colspan="4">负债 · 你尚未偿还的</th></tr>${['mortgage','shortfallDebt'].map(k=>row(names[k],start.liabilities[k],end.liabilities[k])).join('')}${row('负债合计',start.totalLiabilities,end.totalLiabilities,'subtotal')}${row('净资产 = 资产 − 负债',start.netWorth,end.netWorth,'net-total')}</tbody></table></div><p class="table-note">表内按美元分显示；变化用未舍入数值计算，个别行可能存在 $0.01 的显示舍入差。</p>`;}
function incomeTable(h){const rows=[['税后工资',h.income],['基本生活支出',-h.livingExpense],['本年生活选择',-h.choiceCost],['医疗保费',-h.insurancePremium],['医疗费用',-h.medicalCost],['医疗赔付',h.insurancePayout],['其他家庭事件',-h.eventCost],['住房维护',-h.homeMaintenance],['车辆维护',-h.carMaintenance],['按揭利息',-h.mortgageInterest],['借款利息',-h.debtInterest],['购房费用',-h.homePurchaseFee]];return `<div class="table-wrap"><table><thead><tr><th>家庭收支 · 美元</th><th>本年金额</th></tr></thead><tbody>${rows.map(([name,value])=>`<tr><th scope="row">${name}</th><td>${value>=0?'+':'−'}${preciseMoney(Math.abs(value))}</td></tr>`).join('')}<tr class="subtotal"><th>家庭净投入</th><td>${signedMoney(h.netContribution)}</td></tr></tbody></table></div><p class="table-note">按揭本金 ${money(h.mortgagePrincipal)} 属于资产负债转换，不是消费；交易费用 ${money(h.fees)} 已计入投资与资产变动，不重复扣减。</p>`;}
function stat(label,value,note=''){return `<div class="stat-card"><span>${label}</span><strong>${value}</strong><small>${note}</small></div>`;}
function chart(series){const width=1000,height=245,pad={left:64,right:20,top:16,bottom:35};const count=state.round+1;const all=series.flatMap(s=>s.values);const min=Math.min(0,...all),max=Math.max(120000,...all)*1.08;const x=i=>pad.left+i/Math.max(1,count-1)*(width-pad.left-pad.right);const y=v=>height-pad.bottom-(v-min)/(max-min)*(height-pad.top-pad.bottom);return `<svg class="chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="按年末观察的净资产变化曲线"><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#b7c9a4" stop-opacity=".35"/><stop offset="1" stop-color="#b7c9a4" stop-opacity="0"/></linearGradient></defs>${Array.from({length:4},(_,i)=>{const val=min+(max-min)*i/3;return `<line x1="${pad.left}" x2="${width-pad.right}" y1="${y(val)}" y2="${y(val)}" stroke="#e9ede2" stroke-dasharray="3 5"/><text class="chart-label" x="${pad.left-12}" y="${y(val)+3}" text-anchor="end">${(val/10000).toFixed(0)}万</text>`;}).join('')}${series.map((s,index)=>{const d=s.values.map((v,i)=>`${i?'L':'M'}${x(i)},${y(v)}`).join(' ');return `${index===0?`<path d="${d} L${x(s.values.length-1)},${height-pad.bottom} L${pad.left},${height-pad.bottom}Z" fill="url(#chartFill)"/>`:''}<path class="chart-line" d="${d}" fill="none" stroke="${s.color}" stroke-width="${index===0?3:2}" ${index?'stroke-dasharray="5 5"':''}/>${s.values.map((v,i)=>`<circle class="chart-hover" cx="${x(i)}" cy="${y(v)}" r="${index===0?4:3}" fill="${s.color}" stroke="#fff" stroke-width="2"><title>${i?YEARS[i-1].year+' 年末':'起点'} · ${s.name}：${money(v)}</title></circle>`).join('')}`;}).join('')}${Array.from({length:count},(_,i)=>i===0||i===count-1||i%2===0?`<text class="chart-label" x="${x(i)}" y="${height-9}" text-anchor="middle">${i?YEARS[i-1].year:'起点'}</text>`:'').join('')}</svg>`;}
function ledgerPage(){const s=summary(state),index=ledgerYear??state.round-1,record=state.history[index];const lines=[{name:'家庭净资产',color:'#376d58',values:[100000,...state.history.map(h=>h.endNetWorth)]},{name:'初始资产 + 家庭净投入',color:'#c2aa7f',values:[100000,...state.history.map((_,i)=>100000+state.history.slice(0,i+1).reduce((sum,h)=>sum+h.netContribution,0))]},{name:'同桌净资产',color:'#887eaf',values:[100000,...rivalState.history.map(h=>h.endNetWorth)]}];return `<div class="page-heading"><div><div class="eyebrow">THE LEDGER · 每一笔都算清楚</div><h1>你的财富，如何走到今天。</h1></div><button class="secondary" data-action="export">${icon('download')} 导出旅程</button></div><div class="stat-grid">${stat('净资产',money(s.netWorth),'资产减去全部负债')}${stat('家庭净投入',signedMoney(s.netContribution),'税后工资减家庭费用')}${stat('投资与资产变动',signedMoney(s.investmentProfit),'含房价、车折旧，已扣交易费')}${stat('组合年度回撤',(s.maxInvestmentDrawdown*100).toFixed(1)+'%','金融资产年末税费前指数')}</div><section class="card chart-card"><div class="section-heading"><h2>成长轨迹</h2><div class="legend">${lines.map(l=>`<span><i style="background:${l.color}"></i>${l.name}</span>`).join('')}</div></div>${chart(lines)}<p class="table-note">你的净资产与累计净投入线的距离是投资与资产变动；紫线是同桌独立账户。回撤只观察年末，不涵盖年内波动，也不含房车和交易费。</p></section><section class="card ledger-sheet"><div class="section-heading"><h2>年度资产负债表</h2><span class="mini-label">年初 → 年末，逐项核对</span></div>${record?`<div class="year-selector">${state.history.map((h,i)=>`<button class="${i===index?'active':''}" data-action="ledger-year" data-index="${i}">${h.year}</button>`).join('')}</div>${sheetTable(record.startBalanceSheet,record.endBalanceSheet)}${duelResult(index)}<details class="cashflow-details"><summary>展开 ${record.year} 年家庭收支明细</summary>${incomeTable(record)}</details><button class="text-btn" data-action="review" data-index="${index}">重新翻开这一年的故事 ↗</button>`:`<div class="empty-state">第一回合还没结束。<br>先出一张人生牌，账本会在这里长出第一行。</div>${sheetTable(balanceSheet(state),balanceSheet(state))}`}</section>`;}
function profilePage(){return `<div class="page-heading"><div><div class="eyebrow">MEMORY COLLECTION · 每走一年，收藏一页</div><h1>你走过的时代，都在这里。</h1><p>${state.round} / ${YEARS.length} 张时代卡片 · 林舟 ${state.age} 岁</p></div><button class="secondary" data-action="goals">查看人生约定</button></div><div class="badge-shelf">${badges().map(b=>`<div class="badge ${b.unlocked?'unlocked':'locked'}" title="${esc(b.detail)}"><span>${b.unlocked?b.symbol:'?'}</span><b>${b.name}</b><small>${b.unlocked?'已解锁':b.detail}</small></div>`).join('')}</div><div class="memory-grid">${YEARS.map((y,i)=>i<state.round?`<article class="memory-card"><button class="memory-image-button" data-action="review" data-index="${i}"><img src="${HISTORY_MEDIA[y.year]?.path||''}" alt="${esc(HISTORY_MEDIA[y.year]?.title)}" loading="lazy"><span>${y.year}</span></button><div><small>${state.history[i].age-1} 岁的选择</small><h2>${esc(state.history[i].choiceLabel)}</h2><p>生活值 ${state.history[i].lifeDelta>=0?'+':''}${state.history[i].lifeDelta} · 净资产 ${money(state.history[i].endNetWorth)}</p><button class="text-btn" data-action="photo" data-year="${y.year}">影像出处 ↗</button></div></article>`:`<div class="memory-card memory-locked"><span>${icon('lock')}</span><b>${y.year}</b><p>这一页，等你亲自走过。</p></div>`).join('')}</div>`;}
function endingPage(){
 const s=summary(state),baselines=[{name:'同桌的独立旅程',color:'#887eaf',state:rivalState},{name:'固定均衡',color:'#909eae',state:simulateStrategy('balanced')},{name:'全现金',color:'#abc69c',state:simulateStrategy('cash')}];
 const modelRounds=agentRounds.filter(p=>p.source==='model').length;
 const lines=[{name:'你的旅程',color:'#376d58',values:[100000,...state.history.map(h=>h.endNetWorth)]},...baselines.map(b=>({name:b.name,color:b.color,values:[100000,...b.state.history.map(h=>h.endNetWorth)]}))];
 return `<section class="ending"><div class="ending-art"></div><div><div class="eyebrow">CHAPTER COMPLETE · 二十年旅程完成</div><span class="ending-medal">✦</span><h1>你成为了<br>${esc(s.title)}。</h1><p>从 30 岁到 50 岁，有些选择改变了账户，有些选择改变了生活。<br>这二十年，是你的存档。2026 为模拟终章。</p><div class="ending-actions"><button class="primary" data-action="nav" data-page="profile">打开时代相册 ${icon('arrow')}</button><button class="secondary" data-action="restart">再走一条路</button></div></div></section><div class="stat-grid">${stat('最终净资产',money(s.netWorth),`初始购买力约 ${money(s.inflationAdjustedWorth)}`)}${stat('生活值',s.lifeScore+' / 100','模拟剧情指标，不是人格测评')}${stat('人生约定',s.goals.filter(g=>g.achieved).length+' / 3','无缺口借款 · 百万积累 · 生活满意')}${stat('同行的 AI 回合',modelRounds+' / '+YEARS.length,`其余 ${YEARS.length-modelRounds} 年为规则陪练`)}</div>${personaView()}<div class="lesson-grid">${s.lessons.slice(0,3).map((l,i)=>`<div><span>TAKEAWAY 0${i+1}</span><p>${esc(l)}</p></div>`).join('')}</div><section class="card chart-card"><div class="section-heading"><h2>同一段历史，几条不同的路</h2><span class="mini-label">同起点 · 同市场 · 同外生事件</span></div><div class="legend">${lines.map(l=>`<span><i style="background:${l.color}"></i>${l.name}</span>`).join('')}</div>${chart(lines)}<div class="table-wrap"><table><thead><tr><th>路径</th><th>期末净资产</th><th>家庭净投入</th><th>投资与资产变动</th><th>生活值</th></tr></thead><tbody>${[{name:'你的旅程',state},...baselines].map(b=>{const r=summary(b.state);return `<tr><th>${b.name}</th><td>${money(r.netWorth)}</td><td>${money(r.netContribution)}</td><td>${signedMoney(r.investmentProfit)}</td><td>${r.lifeScore}</td></tr>`;}).join('')}</tbody></table></div><p class="table-note">同桌是每年事前封存决定的独立账户，包含 ${modelRounds} 次模型决策与 ${YEARS.length-modelRounds} 次规则决策。固定均衡为宽基40 / 现金20 / 债券30 / 黄金10；固定均衡与全现金不买房车。各路径独立选择家庭方案；差异并非纯配置效应。2026 为模拟行情，历史回放也不证明预测能力。</p><button class="secondary" data-action="nav" data-page="ledger">查看双方完整账本</button></section>`;
}
function render(){persist();const top=window.scrollY;$('#app').innerHTML=header()+`<main class="main">${page==='ledger'?ledgerPage():page==='profile'?profilePage():gamePage()}${footer()}</main>`;window.scrollTo(0,top);}
function showModal(title,body,{wide=false,kicker='LIFE CFO · 人生冒险'}={}){modalReturnFocus=document.activeElement;$('#app').inert=true;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><header class="modal-header"><div><div class="eyebrow">${esc(kicker)}</div><h2 id="modal-title">${title}</h2></div><button class="modal-close" data-action="close-modal" aria-label="关闭">${icon('close')}</button></header><div class="modal-body">${body}</div></section></div>`;$('.modal').focus();}
function closeModal(){if(parentDialog){$('#modal-root').innerHTML=parentDialog;parentDialog=null;$('.modal').focus();return;}const wasReview=pendingReview;if(pendingReview){pendingReview=false;persist();}$('#modal-root').innerHTML='';$('#app').inert=false;if(modalReturnFocus?.isConnected)modalReturnFocus.focus();if(wasReview){prepareRound();render();if(state.round===YEARS.length)void ensurePersona();}}
function annualMood(h){return h.investmentProfit<0?'风浪是剧情的一部分。':h.lifeDelta>=5?'账户在成长，日子也在发光。':'又一年的选择，落进了账本。';}
function review(index,pending=false){const h=state.history[index],y=YEARS[index];if(!h)return;showModal(`${y.year} · ${esc(y.reveal.title)}`,`<div class="annual-result"><span class="result-stamp">年度结算</span><p>${annualMood(h)}</p><strong data-count="${h.endNetWorth}">${money(h.endNetWorth)}</strong><small>年末净资产 · 较年初 ${signedMoney(h.endNetWorth-h.startNetWorth)}</small></div><div class="result-tags"><span>♡ 生活值 ${h.lifeDelta>=0?'+':''}${h.lifeDelta} → ${h.lifeScore}</span><span>▧ ${pending?'时代影像 +1':'已收藏的时代影像'}</span>${h.homePurchase?'<span>⌂ 新家已解锁</span>':''}${h.insurancePayout>0?'<span>☂ 保障赔付 '+money(h.insurancePayout)+'</span>':''}</div>${annualRanking(h,y)}${duelResult(index)}${photoCard(y.year,{compact:true})}<p class="review-story">${esc(y.reveal.text)}</p><div class="result-markets">${ASSET_KEYS.map(k=>`<div><small>${names[k]}</small><b class="${h.returns[k]>=0?'up':'down'}">${percent(h.returns[k])}</b></div>`).join('')}</div><div class="choice-result"><b>你选择了：${esc(h.choiceLabel)}</b><p>${esc(y.event.label)}</p></div><div class="section-heading"><h3>这一年的资产负债表</h3><span class="mini-label">每一项，都写清楚</span></div>${sheetTable(h.startBalanceSheet,h.endBalanceSheet)}<div class="wealth-bridge"><span>年初净资产<b>${money(h.startNetWorth)}</b></span><i>＋</i><span>家庭净投入<b>${signedMoney(h.netContribution)}</b></span><i>＋</i><span>投资与资产变动<b>${signedMoney(h.investmentProfit)}</b></span><i>＝</i><span>年末净资产<b>${money(h.endNetWorth)}</b></span></div><details class="cashflow-details"><summary>展开收入、支出与结算过程</summary>${incomeTable(h)}<ul class="settlement-log">${h.explanation.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></details><div class="lesson"><span>✧ 经验已入袋</span><p>${esc(y.reveal.lesson)}</p></div><button class="primary wide" data-action="continue">${pending?(state.round===YEARS.length?'领取我的二十年结局':'进入 '+YEARS[state.round].year+' · 下一回合'):'合上这一页'} ${icon('arrow')}</button>`,{wide:true,kicker:`ROUND ${String(index+1).padStart(2,'0')} CLEAR · ${h.age} 岁`});animateNumber();}
function animateNumber(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const element=$('[data-count]');if(!element)return;const target=Number(element.dataset.count),start=performance.now();const step=now=>{const p=Math.min((now-start)/650,1);element.textContent=money(target*(1-(1-p)**3));if(p<1&&element.isConnected)requestAnimationFrame(step);};requestAnimationFrame(step);}
function help(){showModal('这二十年，你来出牌。',`<div class="howto-grid"><div><span>01</span><h3>读情报，看看世界</h3><p>历史回合的照片、新闻和市场数字只来自当时已发生的信息；2026 为明确标注的架空情景。不同板块会有不同命运，未来没有提示答案。</p></div><div><span>02</span><h3>选生活，组好投资牌</h3><p>给家人一个决定，再分配现金、股票、国债与黄金。股票可选宽基、科技、消费或医疗。想买房车、续保，可打开“生活计划”。</p></div><div><span>03</span><h3>出发，揭晓这一年</h3><p>每回合一年，完成结算并收藏一张时代照片。资产负债表写清来去，二十年后领取结局。</p></div></div><div class="lesson"><span>三种玩法</span><p>自己玩 · 搭档建议 · 搭档托管。配置 API 后使用真实模型；未配置时是明确标注的规则陪练。搭档有独立账本，每年在结算前封存决定。</p></div><p>本章30岁起步，50岁结束。2007–2025 使用历史行情；2026 是架空模拟终章。家庭、保险、房价均为教学模拟。没有必须买房的标准答案。</p><button class="primary wide" data-action="close-modal">准备好了，开始冒险 ${icon('arrow')}</button>`);}
function intel(){const y=YEARS[state.round];showModal(`${y.year} 年初 · 完整情报`,`<p class="table-note">${esc(y.dataLabel||'历史回放')} · ${esc(y.sectorProxy||'French 行业研究组合')}</p>${(y.aiContext?.length?'<div class="api-boundary"><b>AI 同样可见的匿名情报</b>'+y.aiContext.map(a=>'<p><b>'+esc(a.title)+'</b><br>'+esc(a.text)+'</p>').join('')+'</div>':'')}${y.briefing.map(n=>`<article class="intel-item"><span class="mini-label">${esc(n.tag)}</span><h3>${esc(n.title)}</h3><p>${esc(n.text)}</p>${n.sourceUrl?`<a href="${esc(n.sourceUrl)}" target="_blank" rel="noopener noreferrer">查看原始资料 ↗</a>`:''}</article>`).join('')}<h3 style="margin:22px 0 10px">数字背后的口径</h3>${(y.marketSignals||[]).map(s=>`<article class="intel-item"><h3>${esc(s.label)} · ${esc(s.value)}</h3><p>${esc(s.context)}</p><small>信息时点：${esc(s.asOf)}</small>${s.sourceUrl?`<a href="${esc(s.sourceUrl)}" target="_blank" rel="noopener noreferrer">来源 ↗</a>`:''}</article>`).join('')}<p class="table-note">新闻不等于交易指令。历史资料的外部页面可能包含后续修订或其他年份，请自行决定是否打开。</p>`);}
function showPhoto(year){const m=HISTORY_MEDIA[year];if(!m||year>(state.round===YEARS.length?2026:YEARS[state.round].year-1))return;if($('#modal-root').innerHTML)parentDialog=$('#modal-root').innerHTML;const illustrated=m.kind==='illustration'||m.kind==='scenario';showModal(`${year} · ${esc(m.title)}`,`<img class="source-photo" src="${esc(m.path)}" alt="${esc(m.alt||m.title)}"><p>${esc(m.caption)}</p><div class="photo-attribution"><p>作者：${esc(m.artist)}<br>${illustrated?'事件 / 制作时间':'拍摄时间'}：${esc(m.date)}<br>授权：${esc(m.license)}。${illustrated?'主题图解，不是现场照片。':'页面使用 CSS 裁切；原图内容未修改。'}</p><a href="${esc(m.page)}" target="_blank" rel="noopener noreferrer">${illustrated?'查看原始图解':'原图与署名'} ↗</a>${m.licenseUrl?` · <a href="${esc(m.licenseUrl)}" target="_blank" rel="noopener noreferrer">许可条款 ↗</a>`:''}${m.factSources?.length?`<p>事件资料：${m.factSources.map(source=>`<a href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">${esc(source.title)} ↗</a>`).join(' · ')}</p>`:''}</div>`,{wide:true,kicker:illustrated?'ARCHIVE · 历史主题图解':'ARCHIVE · 历史影像'});}
function sources(){const visible=SOURCES.filter((s,i)=>state.round===YEARS.length||/French|NYU/.test(s.title));showModal('资料室 · 规则和来源',`<p>不靠隐藏加成，也不替你猜明年。本局按同一套年度结算规则运行。</p><ol class="rules-list"><li>年初支付家庭计划和购置款，必要时卖出非现金资产。</li><li>按你给出的比例配置；没有强制现金下限。维持持仓模式不调仓。</li><li>计算全年金融回报、房价变化和车折旧，再结算年度工资、保费、医疗、生活和月供。</li><li>年末现金不够就按比例变现金融资产，仍不足记为缺口借款，下一年按12%收息；结余先还缺口借款。</li><li>保存年初与年末完整资产负债表。工资和投资收益分开记。</li></ol>${visible.map(s=>`<div class="source-item"><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a><p>${esc(s.note)}</p></div>`).join('')}${state.round<YEARS.length?'<p class="table-note">完整宏观背景来源通关后解锁。市场数据外链含后续年份，打开可能提前获知回报。</p>':''}<h3 style="margin-top:22px">本版假设</h3><ul class="rules-list">${ASSUMPTIONS.map(a=>`<li>${esc(a)}</li>`).join('')}</ul><p>历史照片的作者与许可可从图片上的“历史照片”按钮查看。趣味旁白是游戏原创，不是历史人物引语。</p>${legacyRaw?'<button class="secondary" data-action="export-legacy">导出封存的旧版原始旅程</button>':''}`,{wide:true});}

function lifePlan(){const auto=state.mode==='auto';const toggle=(key,title,description,disabled=false)=>`<div class="plan-row"><div><h3>${title}</h3><p>${description}</p></div><button class="switch ${decision[key]?'on':''}" role="switch" aria-label="${title}" aria-checked="${decision[key]}" data-action="toggle-plan" data-key="${key}" ${auto||disabled?'disabled':''}></button></div>`;showModal('把生活安排好。',`${toggle('insurance','家庭医疗保障',`年保费 ${money(RULES.insurancePremium*state.priceIndex)}；本年生效。只覆盖剧情医疗事件，免赔 ${money(RULES.insuranceDeductible*state.priceIndex)}，最高赔付 ${money(RULES.insuranceLimit*state.priceIndex)}。`)}${toggle('buyHome','购入自住房',state.homeValue>0?'已经拥有自己的家。首版不可卖出。':`房价 ${money(state.marketHomePrice)}；首付20%＋费用2%。30年固定5%按揭，另有维护费。`,state.homeValue>0)}${toggle('buyCar','购入家庭汽车',state.carValue>0?'已经拥有车辆，每年折旧15%。首版不可卖出。':`购价 ${money(RULES.carPrice*state.priceIndex)}；全款买入，每年折旧15%并承担维护。`,state.carValue>0)}<div class="plan-row"><div><h3>每年重新配牌</h3><p>关闭后维持原持仓，不按目标比例交易。六类非现金资产每侧交易费0.2%。</p></div><button class="switch ${decision.rebalance==='annual'?'on':''}" role="switch" aria-label="每年重新配牌" aria-checked="${decision.rebalance==='annual'}" data-action="toggle-rebalance" ${auto?'disabled':''}></button></div><button class="primary wide" data-action="close-modal">记下这些安排 ${icon('check')}</button>`);}
function restartPrompt(){showModal('另开一段人生？',`<p>当前旅程会被新的一局替换。你可以先导出决策和账本；封存的旧版本存档不会受影响。</p><p>重玩会标记“已知剧情”，历史回放成绩不能当作预测能力。</p><div class="modal-actions"><button class="secondary" data-action="export">导出当前旅程</button><button class="primary" data-action="confirm-restart">开始新的一局</button></div>`);}
function downloadJSON(content,name){const blob=new Blob([content],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportJourney(){downloadJSON(JSON.stringify({game:'人生 CFO',version:'0.9.0-rc.1',dataVersion:DATA_VERSION,replay,state,rivalState,agentRounds,agentPack,persona,summary:summary(state),rivalSummary:summary(rivalState)},null,2),`人生CFO-v09-${state.round}年旅程.json`);toast('这一段旅程，已经装进文件。');}
function setAllocation(key,value){const weights=grouped(),others=GROUPS.filter(k=>k!==key),remaining=100-value,total=others.reduce((sum,k)=>sum+weights[k],0);weights[key]=value;let used=0;others.forEach((k,i)=>{const n=i===others.length-1?remaining-used:Math.floor(remaining*(total?weights[k]/total:1/others.length));weights[k]=n;used+=n;});distributeGroup(weights);for(const k of GROUPS){$(`#allocation-${k}`).value=weights[k];$(`[data-allocation-value="${k}"]`).innerHTML=`${weights[k]}<small>%</small>`;}$('#allocation-bar').innerHTML=allocationBar();const p=previewDecision(state,decision);$('#budget-preview').innerHTML=budgetPreview(p);$('#decision-errors').innerHTML=p.errors.length?`<div class="error">${p.errors.map(esc).join('<br>')}</div>`:'';$('#settle-button').disabled=!chosen||!p.valid||!agentPack||agentStatus==='running';document.querySelectorAll('.preset-row button').forEach(b=>b.classList.toggle('active',GROUPS.every(k=>PRESETS[b.dataset.preset][k]===weights[k])));document.querySelectorAll('.sector-card').forEach(b=>{const selected=decision.allocation[b.dataset.sector]===weights.equity&&weights.equity>0;b.classList.toggle('active',selected);b.setAttribute('aria-pressed',String(selected));});$('#sector-current').textContent=STOCK_KEYS.filter(k=>decision.allocation[k]>0).length>1?'混合板块':names[selectedSector];persist();}
document.addEventListener('input',event=>{if(event.target.matches('[data-asset]')&&state.mode!=='auto')setAllocation(event.target.dataset.asset,Number(event.target.value));});
document.addEventListener('click',event=>{
  const button=event.target.closest('[data-action]');if(!button||button.disabled)return;event.preventDefault();const action=button.dataset.action;
  if(action==='nav'){page=button.dataset.page;render();window.scrollTo({top:0,behavior:'smooth'});}
  if(action==='news'){newsTab=Number(button.dataset.index);render();}
  if(action==='mode'){if(state.round>=YEARS.length)return;state.mode=button.dataset.mode;if(state.mode==='auto'&&agentPack){decision=structuredClone(agentPack.playerDecision);chosen=true;syncSector();}render();toast(state.mode==='auto'?'托管执行针对你账户的建议，仍需点击推进一年。':state.mode==='assisted'?'先看看搭档的分析，最终由你决定。':'现在，牌在你手里。');}
  if(action==='choice'){decision.choiceId=button.dataset.choice;chosen=true;render();}
  if(action==='preset'){distributeGroup(PRESETS[button.dataset.preset]);render();}
  if(action==='sector'){const total=grouped().equity;selectedSector=button.dataset.sector;STOCK_KEYS.forEach(k=>decision.allocation[k]=k===selectedSector?total:0);render();if(total===0)toast('已选好股票方向，拖动股票牌增加投入比例。');}
  if(action==='ai-settings')aiSettings();if(action==='ai-connect')connectAgent();if(action==='ai-disconnect')disconnectAgent();if(action==='ai-retry')void askAgent();if(action==='ai-fallback')useRuleFallback();
  if(action==='persona-generate'){if(!apiConfig.apiKey)aiSettings();else void ensurePersona(true);}if(action==='persona-fallback'){cancelAgentRequests();persona=fallbackPersona(state,rivalState);personaStatus='ready';render();}
  if(action==='help')help();if(action==='sources')sources();if(action==='advisor')advisor();if(action==='intel')intel();if(action==='photo')showPhoto(Number(button.dataset.year));
  if(action==='goals')showModal('这局游戏，给人生三个约定。',`${goals()}<p>目标是关卡尺度，不是所有家庭都应追求的理财标准。可以从容租房，也可以拥有自己的家。</p>`);
  if(action==='allocation-help')showModal('四张牌，一份属于你的配置。','<p>拖动任意一张牌，其他比例会自动调整，合计始终100%。股票牌可以选择宽基、科技、消费或医疗；切换板块会将全部股票比例放到该方向。</p><p>搭档可能同时持有多个股票板块，界面显示“混合板块”。点击某个板块即可改为集中持有。2007–2018 行业采用 French 研究组合；2019–2025 切换 XLK / XLY / XLV 代理，其中消费变为可选消费。范围和费用口径存在断点；2026 为模拟值。板块可能和宽基重叠。</p><p>不会自动要求你保留现金。年末收支若不足，会卖出资产；资产仍不够才形成缺口借款。交易费用和每年的去向都写在账本里。</p>');
  if(action==='apply-advisor'&&agentPack){decision=structuredClone(agentPack.playerDecision);chosen=true;syncSector();closeModal();render();toast('建议已放进你的牌组，仍可调整。');}
  if(action==='life-plan')lifePlan();
  if(action==='toggle-plan'){decision[button.dataset.key]=!decision[button.dataset.key];render();lifePlan();}
  if(action==='toggle-rebalance'){decision.rebalance=decision.rebalance==='annual'?'hold':'annual';render();lifePlan();}
  if(action==='settle'){try{if(pendingReview||!agentPack||agentStatus!=='ready'||state.round>=YEARS.length)return;if(state.mode==='auto')decision=structuredClone(agentPack.playerDecision);if(state.mode!=='auto'&&!chosen)return;const next=settleDuel(state,rivalState,agentPack,decision,agentRounds);state=next.player;rivalState=next.rival;agentRounds=next.rounds;agentPack=null;agentStatus='idle';pendingReview=true;try{localStorage.setItem(VISITED_KEY,'true');}catch{}chosen=false;newsTab=0;decision=defaultDecision(state);syncSector();render();review(state.round-1,true);}catch(error){toast(error.message);}}
  if(action==='continue'){closeModal();render();window.scrollTo({top:0,behavior:'smooth'});}
  if(action==='close-modal')closeModal();if(action==='review')review(Number(button.dataset.index));
  if(action==='ledger-year'){ledgerYear=Number(button.dataset.index);render();}
  if(action==='restart')restartPrompt();
  if(action==='confirm-restart'){cancelAgentRequests();const mode=state.mode;state=newGame(mode);rivalState=newGame('rival');agentRounds=[];agentPack=null;persona=null;agentStatus='idle';personaStatus='idle';decision=defaultDecision(state);chosen=false;replay=true;pendingReview=false;newsTab=0;ledgerYear=null;page='game';syncSector();closeModal();prepareRound();render();window.scrollTo(0,0);toast('双人新存档已开启 · 已知剧情重玩');}
  if(action==='export')exportJourney();if(action==='export-legacy'&&legacyRaw){downloadJSON(legacyRaw,`人生CFO-${legacyVersion}-封存原档.json`);toast('旧版原始存档已导出，未按新规则改写。');}
});
document.addEventListener('submit',event=>{if(event.target.id==='ai-settings-form'){event.preventDefault();connectAgent();}});
document.addEventListener('keydown',event=>{const modal=$('.modal');if(!modal)return;if(event.key==='Escape'){event.preventDefault();closeModal();}if(event.key==='Tab'){const focusable=[...modal.querySelectorAll('button:not([disabled]),a[href],input,select,summary,[tabindex="0"]')];if(!focusable.length){event.preventDefault();return;}const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&(document.activeElement===first||document.activeElement===modal)){event.preventDefault();last.focus();}else if(!event.shiftKey&&(document.activeElement===last||document.activeElement===modal)){event.preventDefault();first.focus();}}});
prepareRound();render();if(initialMessage)toast(initialMessage);if(pendingReview)review(state.round-1,true);else if(state.round===YEARS.length)ensurePersona();
